// Returns 1 (GPU) if majority of trees vote GPU, else 0 (CPU).
inline int predict(const double* features) {
    int votes_gpu = 0;
    votes_gpu += predict_tree_0(features);
    votes_gpu += predict_tree_1(features);
    votes_gpu += predict_tree_2(features);
    votes_gpu += predict_tree_3(features);
    votes_gpu += predict_tree_4(features);
    votes_gpu += predict_tree_5(features);
    votes_gpu += predict_tree_6(features);
    votes_gpu += predict_tree_7(features);
    votes_gpu += predict_tree_8(features);
    votes_gpu += predict_tree_9(features);
    votes_gpu += predict_tree_10(features);
    votes_gpu += predict_tree_11(features);
    votes_gpu += predict_tree_12(features);
    votes_gpu += predict_tree_13(features);
    votes_gpu += predict_tree_14(features);
    votes_gpu += predict_tree_15(features);
    votes_gpu += predict_tree_16(features);
    votes_gpu += predict_tree_17(features);
    votes_gpu += predict_tree_18(features);
    votes_gpu += predict_tree_19(features);
    return (votes_gpu > N_TREES / 2) ? 1 : 0;
}

// Returns the fraction of trees voting for GPU (0.0 to 1.0).
inline double predict_gpu_probability(const double* features) {
    int votes_gpu = 0;
    votes_gpu += predict_tree_0(features);
    votes_gpu += predict_tree_1(features);
    votes_gpu += predict_tree_2(features);
    votes_gpu += predict_tree_3(features);
    votes_gpu += predict_tree_4(features);
    votes_gpu += predict_tree_5(features);
    votes_gpu += predict_tree_6(features);
    votes_gpu += predict_tree_7(features);
    votes_gpu += predict_tree_8(features);
    votes_gpu += predict_tree_9(features);
    votes_gpu += predict_tree_10(features);
    votes_gpu += predict_tree_11(features);
    votes_gpu += predict_tree_12(features);
    votes_gpu += predict_tree_13(features);
    votes_gpu += predict_tree_14(features);
    votes_gpu += predict_tree_15(features);
    votes_gpu += predict_tree_16(features);
    votes_gpu += predict_tree_17(features);
    votes_gpu += predict_tree_18(features);
    votes_gpu += predict_tree_19(features);
    return static_cast<double>(votes_gpu) / static_cast<double>(N_TREES);
}

